// The innovators: the people who designed synthesizers and founded the companies that made them. Shape: see CONTRACT.md → Databank.
export default [
  { id: 'robert-moog', name: 'Robert Moog', born: '1934', died: '2005', country: 'US', companies: ['R. A. Moog Co.', 'Moog Music', 'Big Briar'],
    summary: 'American engineer who built the Moog modular synthesizer and, with his staff, the Minimoog.',
    story: 'Moog grew up in New York and was building and selling theremin kits while still a student, which led to his first company. In 1964, working with the composer Herb Deutsch, he built voltage-controlled oscillators and amplifiers that became the Moog modular system, sold to studios, universities and musicians such as Wendy Carlos. In 1970 the company put a fixed set of modules into a portable case with a keyboard as the Minimoog, developed from a prototype by his engineer Bill Hemsath with Jim Scott and Chad Hunt. Financial trouble led to the company being sold, and Moog left in 1977 and founded Big Briar in Asheville, North Carolina, making theremins and effects pedals. He won back the Moog Music name in 2002 and released the Minimoog Voyager before he died of a brain tumour in 2005.',
    innovations: ['Built modules whose pitch and level were set by control voltages, so one module could play or shape another, with pitch following an exponential 1 V/octave scale.',
      'Designed the transistor ladder filter, a four-pole lowpass filter he patented in 1969.',
      'Put a fixed set of synthesizer functions with a keyboard, pitch wheel and modulation wheel into one portable instrument with the Minimoog in 1970.'] },
  { id: 'herb-deutsch', name: 'Herbert Deutsch', born: '1932', died: '2022', country: 'US', companies: ['R. A. Moog Co.'],
    summary: 'American composer and teacher who worked with Robert Moog on the first Moog synthesizer modules.',
    story: 'Deutsch taught music at Hofstra University on Long Island and was writing electronic music on tape when he met Robert Moog at a music teachers’ convention in 1963. In 1964 he spent time at Moog’s workshop in Trumansburg, New York, where the two worked out the first voltage-controlled modules. He used the prototype to make the piece “Jazz Images”, one of the first recordings made on a Moog. He went on to teach electronic music at Hofstra for decades and remained connected with the Moog company and the Bob Moog Foundation.',
    innovations: ['Asked for the modules to be played from an organ-style keyboard, which became the standard controller for the Moog and most synthesizers after it.',
      'Made one of the first pieces of music on a Moog prototype, “Jazz Images”, in 1964.'] },
  { id: 'alan-r-pearlman', name: 'Alan R. Pearlman', born: '1925', died: '2019', country: 'US', companies: ['Nexus Research Laboratory', 'ARP Instruments'],
    summary: 'American engineer who founded ARP Instruments and led the design of the ARP 2500, 2600 and Odyssey.',
    story: 'Pearlman was an electronics engineer who had built amplifiers for the space programme and founded Nexus Research Laboratory, a maker of operational amplifiers, in 1960. In 1969 he founded ARP Instruments near Boston with David Friend and Lewis Pollock, aiming to build synthesizers whose oscillators stayed in tune. ARP’s first product was the large 2500 modular, followed by the semi-modular 2600 in 1971 and the Odyssey in 1972. By the mid-1970s ARP sold more synthesizers than any other maker, but the cost of developing the Avatar guitar synthesizer and internal disputes led to the company closing in 1981. Korg later reissued the Odyssey and the 2600 with Pearlman’s approval.',
    innovations: ['Used his operational amplifier work to make oscillators that held their tuning far better than earlier designs.',
      'Replaced patch cords with a grid of sliding matrix switches on the ARP 2500.',
      'Wired the 2600’s modules together behind the panel, with a printed signal flow, so it made sound without patch cords and cords were used only to change the wiring.'] },
  { id: 'dennis-colin', name: 'Dennis Colin', country: 'US', companies: ['ARP Instruments'],
    summary: 'American engineer at ARP Instruments who designed the ARP 2500 and ARP 2600 with Alan R. Pearlman.',
    story: 'Colin was one of ARP’s first engineers after the company was founded near Boston in 1969. He worked with Alan R. Pearlman and David Friend on the 2500 modular, ARP’s first instrument. He then led the engineering of the 2600 with Pearlman, a semi-modular built for teaching that ARP introduced in 1971. Little has been published about his life outside ARP.',
    innovations: ['Co-designed the ARP 2600, whose pre-wired but patchable layout became the standard teaching synthesizer of the 1970s.',
      'Worked on the ARP 2500, with its matrix switches in place of patch cords.'] },
  { id: 'david-friend', name: 'David Friend', country: 'US', companies: ['ARP Instruments', 'Computer Pictures Corporation', 'Pilot Software', 'Carbonite', 'Wasabi Technologies'],
    summary: 'American engineer who co-founded ARP Instruments and designed the ARP Odyssey.',
    story: 'Friend studied music and electrical engineering at Yale and was a graduate student at Princeton when he left to co-found ARP Instruments with Alan R. Pearlman in 1969. He worked on the 2500 and 2600 and designed the Odyssey, a smaller keyboard synthesizer released in 1972 to compete with the Minimoog. He became ARP’s president before the company closed in 1981. He went on to co-found software and internet companies, among them Carbonite, the online backup service, and Wasabi, a cloud storage company.',
    innovations: ['Designed the ARP Odyssey, a portable synthesizer with two oscillators that could play two notes at once, at a time when most keyboard synthesizers played one.',
      'Gave every setting on the Odyssey its own slider, so a sound could be read from the panel at a glance.'] },
  { id: 'don-buchla', name: 'Don Buchla', born: '1937', died: '2016', country: 'US', companies: ['Buchla & Associates', 'Buchla Electronic Musical Instruments'],
    summary: 'American engineer who built the Buchla modular synthesizers and the Music Easel.',
    story: 'Buchla studied physics at the University of California, Berkeley. In 1963 the composers Morton Subotnick and Ramon Sender of the San Francisco Tape Music Center asked him to build an electronic instrument, and the result was the Buchla 100 series modular, developed alongside Moog’s work on the other side of the country. He avoided the organ keyboard, using touch-sensitive metal plates instead, and built sequencers, complex oscillators and lowpass gates. The Music Easel of 1973 put these ideas into one portable case. He later designed MIDI controllers such as Thunder and Lightning, and the company was sold in 2012.',
    innovations: ['Built one of the first voltage-controlled step sequencers, the sequential voltage source in the 100 series.',
      'Designed the lowpass gate, a filter and amplifier in one that uses a light-dependent resistor and gives struck, decaying notes.',
      'Built complex oscillators that shape their own waveforms by folding, in place of filtering a bright wave.',
      'Used flat touch plates that sense pressure and position in place of a mechanical keyboard.'] },
  { id: 'david-cockerell', name: 'David Cockerell', country: 'GB', companies: ['Electronic Music Studios', 'Electro-Harmonix', 'Akai'],
    summary: 'British engineer who designed the electronics of the EMS VCS3, Synthi AKS and Synthi 100.',
    story: 'Peter Zinovieff hired Cockerell in 1966 to build equipment for his studio in Putney, London. When Zinovieff, Tristram Cary and Cockerell founded Electronic Music Studios in 1969, Cockerell designed the electronics of the VCS3, then the Synthi AKS and the large Synthi 100. In the 1970s he moved to Electro-Harmonix in New York, designing guitar pedals such as the Small Stone phaser and Electric Mistress flanger and, later, early digital delays. At Akai he designed the hardware of the S612, S900 and S1000 samplers, and he later returned to Electro-Harmonix.',
    innovations: ['Designed the VCS3, one of the first small, affordable synthesizers, in which modules are connected by pins in a matrix in place of patch cords.',
      'Designed the hardware of Akai’s S900 and S1000 samplers, with Chris Huggett writing the S1000’s operating system.'] },
  { id: 'peter-zinovieff', name: 'Peter Zinovieff', born: '1933', died: '2021', country: 'GB', companies: ['Electronic Music Studios'],
    summary: 'British composer and engineer who founded Electronic Music Studios and specified the VCS3.',
    story: 'Zinovieff was born in London to Russian parents and trained as a geologist before setting up an electronic music studio in his house in Putney in the 1960s. He bought minicomputers to control the studio and, with programmers including Peter Grogono, wrote software to sequence and analyse sound. He founded EMS in 1969 with Tristram Cary and David Cockerell to pay for the studio by selling synthesizers, and specified the set of modules in the VCS3. EMS ran into financial trouble in the late 1970s and was sold, and Zinovieff later wrote opera libretti, including Harrison Birtwistle’s “The Mask of Orpheus”.',
    innovations: ['Ran one of the first computer-controlled electronic music studios, using DEC PDP-8 minicomputers to sequence and control equipment.',
      'Specified the VCS3, a complete synthesizer small enough to sit on a table, sold from 1969.'] },
  { id: 'tristram-cary', name: 'Tristram Cary', born: '1925', died: '2008', country: 'GB', companies: ['Electronic Music Studios'],
    summary: 'British composer who co-founded Electronic Music Studios and designed the case of the VCS3.',
    story: 'Cary, son of the novelist Joyce Cary, learned electronics as a radar officer in the Royal Navy during the Second World War and built one of the first electronic music studios in Britain after it. He wrote electronic scores for film and television, among them “Quatermass and the Pit” and early “Doctor Who” serials. In 1967 he founded the electronic music studio at the Royal College of Music, and in 1969 he co-founded EMS with Peter Zinovieff and David Cockerell. He moved to Australia in the 1970s and taught at the University of Adelaide.',
    innovations: ['Designed the VCS3’s case, a wooden cabinet with an angled panel and the pin matrix in view, which set how the instrument looked.',
      'Founded the electronic music studio at the Royal College of Music in 1967, one of the first in a British conservatoire.'] },
  { id: 'chris-huggett', name: 'Chris Huggett', born: '1949', died: '2020', country: 'GB', companies: ['Electronic Dream Plant', 'Oxford Synthesiser Company', 'Akai', 'Novation'],
    summary: 'British engineer who designed the EDP Wasp, the OSCar and work on Novation’s Bass Station.',
    story: 'Huggett formed Electronic Dream Plant in 1977 with the musician Adrian Wagner, aiming to build a cheap synthesizer that kept a good sound by saving on the case and controls. The result was the Wasp of 1978, followed by the Gnat, the Spider sequencer and the Caterpillar keyboard. After EDP closed he founded the Oxford Synthesiser Company and designed the OSCar, released in 1983. He then wrote the operating system for the Akai S1000 sampler and advised Novation, working on the Bass Station and later instruments. He died of cancer in 2020.',
    innovations: ['Used digital CMOS oscillators and a flat touch-sensitive keyboard on the Wasp to bring the price below £200.',
      'Gave the OSCar user-drawn waveforms built from harmonics alongside its analogue filter, an early hybrid of digital oscillators and analogue filtering.',
      'Wrote the operating system for the Akai S1000 sampler.'] },
  { id: 'adrian-wagner', name: 'Adrian Wagner', born: '1952', died: '2018', country: 'GB', companies: ['Electronic Dream Plant'],
    summary: 'British composer who co-founded Electronic Dream Plant and co-created the Wasp synthesizer.',
    story: 'Wagner was a great-great-grandson of the composer Richard Wagner and was born in Kent. He released electronic albums in the 1970s and worked with the BBC Radiophonic Workshop. In 1977 he formed Electronic Dream Plant with the engineer Chris Huggett to make an inexpensive synthesizer, and the company sold the Wasp from 1978, followed by the Gnat, Spider and Caterpillar, all named after insects. He later wrote music for television, including the theme for “Trans World Sport”.',
    innovations: ['Set the brief for the Wasp: a synthesizer cheap enough for musicians who could not buy a Minimoog, with a built-in speaker and battery power.'] },
  { id: 'fumio-mieda', name: 'Fumio Mieda', country: 'JP', companies: ['Korg'],
    summary: 'Japanese engineer who designed Korg’s first synthesizers, among them the miniKORG 700 and the MS-20.',
    story: 'In 1967 Mieda, an engineer who wanted to build keyboard instruments, approached Tsutomu Katoh of Keio Electronic Laboratories, the company that became Korg. Katoh asked him for a prototype, and Mieda returned about eighteen months later with a programmable organ. That work led to the Korgue synthesizer organ and then to the miniKORG 700 of 1973, Korg’s first synthesizer. He designed the circuits of the MS-20, released in 1978, and decades later led the work on the MS-20 mini of 2013.',
    innovations: ['Designed the miniKORG 700, one of the first synthesizers made in Japan.',
      'Designed the MS-20, a patchable monosynth with an external signal processor that turns the pitch and loudness of an outside sound into control voltages.'] },
  { id: 'tom-oberheim', name: 'Tom Oberheim', born: '1936', country: 'US', companies: ['Oberheim Electronics', 'Marion Systems'],
    summary: 'American engineer who founded Oberheim Electronics and built the SEM, the multi-voice SEM synthesizers and the OB series.',
    story: 'Oberheim was working as a computer engineer in Los Angeles when he began building effects, including a ring modulator and phase shifter sold under the Maestro name. In 1974 he released the Synthesizer Expander Module, or SEM, to add a voice to a Minimoog or ARP, and he then combined SEMs with a keyboard as the Two Voice, Four Voice and Eight Voice. The OB-X of 1979 and the OB-Xa and OB-8 that followed were polysynths with patch memory, and the DMX drum machine came in 1981. He left the company in 1985 and later founded Marion Systems. In 2019 he regained the Oberheim name and in 2022 released the OB-X8 with Sequential.',
    innovations: ['Built the SEM as an expander module played by another synthesizer’s control voltages, with a two-pole multimode filter.',
      'Combined several SEMs under one keyboard in the Two Voice and Four Voice, among the first polyphonic synthesizers on sale.',
      'Linked Oberheim synthesizers, drum machines and sequencers with his own parallel bus before MIDI.'] },
  { id: 'carmine-bonanno', name: 'Carmine Bonanno', country: 'US', companies: ['Octave Electronics', 'Octave-Plateau Electronics', 'Voyetra Technologies', 'Voyetra Turtle Beach'],
    summary: 'American engineer who founded Octave Electronics and designed the Octave CAT.',
    story: 'Bonanno built a prototype synthesizer after graduating in electrical engineering in 1975 and showed it to the owners of Syn-Cordion, a New York maker of accordion electronics. Together they formed Octave Electronics to make it, and the CAT went on sale in late 1976 at $599, about half the price of its competitors. Octave followed it with the Kitten and became Octave-Plateau, which made the Voyetra Eight polysynth. The company turned to music software for personal computers as Voyetra Technologies and merged with Turtle Beach, the business that became Turtle Beach Corporation.',
    innovations: ['Designed the CAT, a two-oscillator monosynth sold for $599 in 1976, around half the price of the Minimoog and Odyssey.',
      'Moved the company from synthesizers into sequencing and sound software for personal computers in the 1980s.'] },
  { id: 'ruben-fernandez', name: 'Ruben Fernandez', country: 'FR', companies: ['RSF'],
    summary: 'French engineer who co-founded RSF in Toulouse with his brother Serge and built the Kobol and Polykobol.',
    story: 'Ruben and Serge Fernandez began making small electronic modules as students in Toulouse in the early 1970s and built their first modular synthesizer, the Series 11, in 1976. After studying an EMS Synthi lent to them by Klaus Schulze, they founded RSF, from their initials, in 1977. The Kobol, a programmable monosynth, followed in 1978 and the Kobol Expander in 1979. The brothers separated in 1981, and Ruben carried on making synthesizers at Saint-Sulpice-sur-Lèze; RSF went bankrupt in 1982, and after a takeover he completed the Polykobol II in 1983, which sold poorly because it was unreliable and expensive. He later moved into computing.',
    innovations: ['Co-designed the Kobol, a monosynth that could store and recall sounds in 1978, when few monosynths had patch memory.',
      'Built the Blackbox, a module that made a monophonic synthesizer play chords.'] },
  { id: 'serge-fernandez', name: 'Serge Fernandez', country: 'FR', companies: ['RSF'],
    summary: 'French engineer who co-founded RSF in Toulouse with his brother Ruben and co-designed the Kobol.',
    story: 'Serge and Ruben Fernandez began making electronic modules as students in Toulouse and built their first modular synthesizer in 1976. They founded RSF in 1977 and released the Kobol in 1978, a programmable monosynth used by Jean-Michel Jarre, Vangelis and Peter Gabriel, and the rack-mounted Kobol Expander in 1979. Fewer than a few hundred Kobols were made. The brothers separated in 1981, and Serge went on to run a business in high-end audiovisual systems that kept the RSF name.',
    innovations: ['Co-designed the Kobol, one of the first monosynths with patch memory, made in France in 1978.'] },
  { id: 'ikutaro-kakehashi', name: 'Ikutaro Kakehashi', born: '1930', died: '2017', country: 'JP', companies: ['Ace Tone', 'Roland', 'ATV'],
    summary: 'Japanese engineer and businessman who founded Ace Tone and Roland and worked with Dave Smith to create MIDI.',
    story: 'Kakehashi was orphaned young and ran a watch and radio repair shop in Osaka before turning to electronic instruments. In 1960 he founded Ace Electronic, which sold organs, amplifiers and rhythm machines as Ace Tone. He left in 1972 and founded Roland in Osaka, which made synthesizers, drum machines such as the TR-808, guitar products and, later, digital pianos. In the early 1980s he worked with Dave Smith of Sequential Circuits and other makers on a common digital interface, published as MIDI in 1983. He left Roland in 2013 and founded ATV.',
    innovations: ['Made early automatic rhythm machines at Ace Tone, such as the Rhythm Ace.',
      'Developed MIDI with Dave Smith, released in 1983, and shared a Technical Grammy with him for it in 2013.',
      'Led Roland as it made programmable drum machines, including the TR-808 and TR-909, a standard part of studio equipment.'] },
  { id: 'tadao-kikumoto', name: 'Tadao Kikumoto', country: 'JP', companies: ['Roland'],
    summary: 'Japanese engineer who designed the Roland TB-303 and TR-909.',
    story: 'Kikumoto joined Roland in its early years and worked as an engineer on its drum machines. He designed the TB-303, released in 1981 as a bass accompaniment machine for guitarists playing alone, and the TR-909 drum machine of 1983. The TB-303 sold poorly and was discontinued, but cheap second-hand units were used to make acid house in Chicago from the mid-1980s. He rose to senior managing director and head of Roland’s research and development, took part in the work on MIDI, and received the MIDI Association’s lifetime achievement award in 2024.',
    innovations: ['Designed the TB-303, a monosynth with a built-in step sequencer whose accent and slide settings give its lines their sound.',
      'Designed the TR-909, which mixed analogue drum circuits with digitally sampled cymbals and hi-hats.'] },
  { id: 'dave-smith', name: 'Dave Smith', born: '1950', died: '2022', country: 'US', companies: ['Sequential Circuits', 'Seer Systems', 'Dave Smith Instruments', 'Sequential'],
    summary: 'American engineer who founded Sequential Circuits, designed the Prophet-5 and proposed MIDI.',
    story: 'Smith studied computer science and electrical engineering at Berkeley and started Sequential Circuits in 1974 to sell an analogue sequencer he had designed. In 1978 he released the Prophet-5, designed with John Bowen, a five-voice polysynth controlled by a microprocessor. In 1981 he proposed a common digital interface between instruments, and his work with Ikutaro Kakehashi of Roland and others became MIDI in 1983. Sequential was sold to Yamaha in 1987; Smith then worked on the Korg Wavestation, founded Seer Systems to make software synthesizers, and in 2002 started Dave Smith Instruments, which got the Sequential name back from Yamaha in 2015. He died in 2022.',
    innovations: ['Made the Prophet-5, the first polysynth that stored every setting of a sound in memory and recalled it at the press of a button.',
      'Proposed the Universal Synthesizer Interface in 1981, which became MIDI, and shared a Technical Grammy with Ikutaro Kakehashi for it in 2013.',
      'Introduced vector synthesis, blending four sound sources with a joystick, on the Prophet VS in 1986.'] },
  { id: 'john-bowen', name: 'John Bowen', country: 'US', companies: ['Sequential Circuits', 'John Bowen Synth Design'],
    summary: 'American sound designer who co-designed the Prophet-5 and programmed its factory sounds.',
    story: 'Bowen worked with Dave Smith on the Prophet-5 and joined Sequential Circuits as its first product specialist. He programmed the original 40 factory sounds of the Prophet-5 and most of the factory sounds and sequences for later Sequential instruments, including the Prophet-10, Prophet T-8 and Prophet VS. He later designed sounds and instruments for Korg, Yamaha and Creamware, and released his own synthesizer, the Solaris, through John Bowen Synth Design. In 2015 he recreated the Prophet-5 factory sounds for the Sequential Prophet-6.',
    innovations: ['Programmed the Prophet-5’s factory sounds, among the first sets of stored presets shipped with a synthesizer.',
      'Designed the Solaris, a large digital synthesizer with many oscillator and filter models.'] },
  { id: 'john-chowning', name: 'John Chowning', born: '1934', country: 'US', companies: ['Stanford University', 'CCRMA'],
    summary: 'American composer who discovered FM synthesis at Stanford, which Yamaha licensed for the DX7.',
    story: 'Chowning studied composition and came to Stanford University, where he worked on computer music. In 1967 he found that modulating the frequency of one oscillator with another at audio rates gave a wide range of complex tones from very little computation. Stanford patented the method and licensed it to Yamaha in the 1970s, and Yamaha used it in the GS1 and then the DX7 of 1983, the best-selling synthesizer of its time. The licence became one of the most valuable Stanford had held. Chowning founded the Center for Computer Research in Music and Acoustics (CCRMA) at Stanford in 1975 and composed pieces such as “Stria” and “Turenas”.',
    innovations: ['Discovered frequency modulation synthesis, making bright, changing tones from a pair of sine-wave oscillators.',
      'Licensed FM through Stanford to Yamaha, which used it in the DX7 and many later instruments.',
      'Founded CCRMA at Stanford in 1975.'] },
  { id: 'uli-behringer', name: 'Uli Behringer', born: '1961', country: 'CH', companies: ['Behringer', 'Music Tribe'],
    summary: 'Swiss engineer who founded Behringer and turned it into a maker of low-priced synthesizers, many copied from older designs.',
    story: 'Behringer was born in Switzerland to a family of musicians and built his first products, a synthesizer and studio equipment, as a student. He founded Behringer in Willich, Germany, in 1989, making mixers and signal processors, and moved manufacturing to China, where the company built its own factory. Through Music Group, later Music Tribe, he bought brands including Midas, Klark Teknik, TC Electronic and Tannoy. Behringer entered synthesizers with the DeepMind 12 in 2016 and then released many low-priced versions of older instruments such as the Minimoog, ARP Odyssey and Roland SH-101, which some designers and other makers have criticised.',
    innovations: ['Made versions of older analogue synthesizers at a fraction of their original price by producing them in his own factory in large numbers.',
      'Had Music Tribe’s chip company, Coolaudio, make copies of discontinued analogue integrated circuits used in those designs.'] },
  { id: 'harald-bode', name: 'Harald Bode', born: '1909', died: '1987', country: 'DE', companies: ['Estey Organ', 'Bode Sound Co.'],
    summary: 'German engineer who built early electronic instruments and proposed a modular synthesizer before Moog and Buchla.',
    story: 'Bode built electronic instruments in Germany from the 1930s, including the Warbo Formant-Orgel and, after the war, the Melochord, which was used in the electronic music studio of West German Radio in Cologne. He moved to the United States in 1954 and worked for the Estey Organ company and in industry. Around 1960 he described a system of separate sound-processing units joined together, an early form of the modular synthesizer. Moog later made his ring modulator and frequency shifter under licence, and in the 1970s he built a vocoder sold under his own name.',
    innovations: ['Built the Warbo Formant-Orgel in 1937, an early polyphonic electronic instrument.',
      'Described a modular system of separate, connectable sound units around 1960.',
      'Designed a frequency shifter and ring modulator that Moog made under licence.'] },
  { id: 'raymond-scott', name: 'Raymond Scott', born: '1908', died: '1994', country: 'US', companies: ['Manhattan Research Inc.'],
    summary: 'American bandleader and composer who built electronic instruments and sequencers at his own company, Manhattan Research.',
    story: 'Scott led the Raymond Scott Quintette in the 1930s, and his tunes such as “Powerhouse” were later used in Warner Bros. cartoons. He founded Manhattan Research in 1946 to build electronic instruments and make music for advertising. He patented the Clavivox, a keyboard instrument, and spent years building the Electronium, a machine meant to compose and play music by itself. Robert Moog built circuits for him in the 1950s and 1960s. In 1971 he went to work for Motown in Los Angeles as head of electronic research.',
    innovations: ['Built early electronic sequencers that played patterns of notes automatically, before commercial synthesizers had them.',
      'Built the Electronium, an instrument meant to generate music of its own rather than be played note by note.',
      'Released “Soothing Sounds for Baby” in 1964, early albums of electronic music made on his own equipment.'] },
  { id: 'tsutomu-katoh', name: 'Tsutomu Katoh', born: '1926', died: '2011', country: 'JP', companies: ['Keio Electronic Laboratories', 'Korg'],
    summary: 'Japanese businessman who co-founded the company that became Korg.',
    story: 'Katoh ran a nightclub in Tokyo, where the accordionist Tadashi Osanai played with a Wurlitzer rhythm machine. In 1962 the two founded Keio Gijutsu Kenkyujo to make a better one, and in 1963 they released the Donca-Matic rhythm machine. In 1967 Katoh backed the engineer Fumio Mieda’s work on a keyboard instrument, which led to Korg’s first synthesizer, the miniKORG 700, in 1973. Under Katoh Korg also made electronic tuners and bought the Vox brand. He died in 2011.',
    innovations: ['Released the Donca-Matic, an early electronic rhythm machine, in 1963.',
      'Put Korg into electronic tuners with the WT-10 of 1975, one of the first handheld tuners.'] },
  { id: 'leon-theremin', name: 'Leon Theremin', born: '1896', died: '1993', country: 'RU', companies: ['Physico-Technical Institute, Petrograd'],
    summary: 'Russian physicist who invented the theremin, played without being touched, and built the Rhythmicon with Henry Cowell.',
    story: 'Lev Termen was working on proximity sensors at a physics institute in Petrograd when he found that the hand’s distance from an antenna could change the pitch of an oscillator, and he showed the result as a musical instrument in 1920. He toured Europe and arrived in the United States in 1927, patented the instrument in 1928 and licensed it to RCA, which made it from 1929. In New York he also built the Terpsitone, played by a dancer, and in 1931 the Rhythmicon with the composer Henry Cowell. He returned to the Soviet Union in 1938, was imprisoned, and worked in a secret laboratory, where he designed the listening device hidden in a carved Great Seal given to the American ambassador. He travelled abroad again from 1989 and died in Moscow in 1993.',
    innovations: ['Made the theremin, an electronic instrument played by moving the hands near two antennas, one for pitch and one for volume, with no contact at all.',
      'Built the Rhythmicon with Henry Cowell in 1931, a keyboard machine that played repeating rhythms in fixed ratios, often called the first drum machine.'] },
  { id: 'maurice-martenot', name: 'Maurice Martenot', born: '1898', died: '1980', country: 'FR', companies: [],
    summary: 'French cellist and radio telegrapher who invented the ondes Martenot.',
    story: 'Martenot was a cellist who served as a radio telegrapher in the First World War, where he noticed the pure tones made by vacuum-tube oscillators. He began work on an instrument based on them in 1918 and presented the ondes Martenot in Paris in 1928. He toured with it, playing with the Philadelphia Orchestra under Leopold Stokowski in 1930, and composers such as Olivier Messiaen, Arthur Honegger and Edgard Varèse wrote for it. He taught at the Paris Conservatoire in the 1940s and trained the first players of the instrument, among them his sister Ginette Martenot and Jeanne Loriod.',
    innovations: ['Gave the ondes Martenot a ring on a wire, pulled along in front of the keyboard, for gliding pitch, and a pressure-sensitive key for shaping loudness.',
      'Made a set of loudspeakers for the instrument, among them one with resonating strings and one with a gong, which colour its sound.'] },
  { id: 'friedrich-trautwein', name: 'Friedrich Trautwein', born: '1888', died: '1956', country: 'DE', companies: ['Rundfunkversuchsstelle', 'Telefunken'],
    summary: 'German engineer who invented the Trautonium in Berlin in 1930.',
    story: 'Trautwein studied electrical engineering and physics and received his first patent for electrical sound generation in 1922. In 1929 he took a post at the broadcasting research unit of the Berlin music academy, where he completed the Trautonium in 1930, working with Paul Hindemith and the student Oskar Sala. Hindemith wrote pieces for it, and Telefunken made a version, the Volkstrautonium, from 1933 to 1935. Trautwein joined the Nazi party in 1933. After the war he taught at the conservatory in Düsseldorf and in 1952 developed the Elektronisches Monochord for the electronic music studio of West German Radio in Cologne.',
    innovations: ['Built the Trautonium, played by pressing a wire against a metal rail, so pitch could be played anywhere along it, not only in fixed steps.',
      'Shaped the Trautonium’s bright tone with resonant filters that imitate the formants of the voice.'] },
  { id: 'oskar-sala', name: 'Oskar Sala', born: '1910', died: '2002', country: 'DE', companies: ['Mars Film'],
    summary: 'German composer who played the Trautonium and developed it into the Mixtur-Trautonium, heard on Hitchcock’s The Birds.',
    story: 'Sala studied piano and composition with Paul Hindemith in Berlin from 1929 and learned the Trautonium as it was being built by Friedrich Trautwein. He carried on developing it himself, finishing the Mixtur-Trautonium in the late 1940s and presenting it in 1952. In 1958 he set up his own studio in Berlin and made electronic scores and sound effects for many films. His best-known work is the bird sounds for Alfred Hitchcock’s “The Birds” (1963), made entirely on the Mixtur-Trautonium. He played and worked on the instrument until his death in Berlin in 2002.',
    innovations: ['Built the Mixtur-Trautonium, whose oscillators produce subharmonics, notes at fractions of the main pitch, in place of the usual overtones.',
      'Made the sound effects for “The Birds” (1963) on an electronic instrument, in place of recordings of real birds.'] },
  { id: 'laurens-hammond', name: 'Laurens Hammond', born: '1895', died: '1973', country: 'US', companies: ['Hammond Clock Company', 'Hammond Organ Company'],
    summary: 'American engineer who invented the Hammond organ and, with his staff, the Novachord.',
    story: 'Hammond studied mechanical engineering at Cornell and founded the Hammond Clock Company in 1928, making clocks driven by synchronous motors. He used the same kind of motor to turn tonewheels, and the Hammond organ went into production in 1935. In 1939 his company showed the Novachord at the New York World’s Fair, designed by Hammond with his engineers John Hanert and C. N. Williams. Only 1,069 were made before wartime shortages stopped production in 1942. He held 91 patents and retired from the company in 1960.',
    innovations: ['Made the Novachord in 1939, a fully polyphonic electronic keyboard with filters and selectable attack and decay shapes, the same subtractive approach later synthesizers used.',
      'Generated organ tones with spinning tonewheels driven by a synchronous motor, so the Hammond organ never went out of tune.'] },
  { id: 'hugh-le-caine', name: 'Hugh Le Caine', born: '1914', died: '1977', country: 'CA', companies: ['National Research Council of Canada'],
    summary: 'Canadian physicist who built the Electronic Sackbut and many studio instruments at the National Research Council.',
    story: 'Le Caine was born in Port Arthur, Ontario, and worked as a physicist at the National Research Council of Canada on radar and atomic physics. In his own time, from 1945, he built the Electronic Sackbut, a monophonic keyboard instrument made to be played with as much expression as an acoustic one. From 1954 he worked full time at the Council’s electronic music laboratory, where he built more than twenty instruments, among them a multi-track tape machine and the Serial Sound Structure Generator, an early sequencer. His piece “Dripsody” (1955) was made from the sound of one drop of water on tape. He helped the University of Toronto and McGill set up their electronic music studios and died after a motorcycle accident in 1977.',
    innovations: ['Built the Electronic Sackbut, whose keys responded to pressure and sideways movement, so each note could be bent and shaped while it played.',
      'Gave the Sackbut separate controls for the left hand that changed the timbre while the right hand played, a forerunner of modulation controls on later synthesizers.'] },
  { id: 'harry-olson', name: 'Harry F. Olson', born: '1901', died: '1982', country: 'US', companies: ['RCA'],
    summary: 'American acoustical engineer at RCA who designed the RCA Mark I and Mark II synthesizers with Herbert Belar.',
    story: 'Olson joined RCA’s laboratories in New Jersey in 1928 after his doctorate and led its acoustic research for decades. He designed microphones such as the RCA 44 and 77 and worked on loudspeakers, tape recording and underwater sound. After the war he and Herbert Belar built a machine that made music from electronic tones under programmed control, the RCA Mark I synthesizer, and then the larger Mark II. The Mark II went to the Columbia-Princeton Electronic Music Center in New York in 1957. Olson retired from RCA in 1967.',
    innovations: ['Built the RCA Mark II with Herbert Belar, a synthesizer controlled by punched paper rolls, so a whole piece could be programmed in place of spliced together on tape.'] },
  { id: 'herbert-belar', name: 'Herbert Belar', born: '1901', died: '1997', country: 'US', companies: ['RCA'],
    summary: 'American engineer at RCA who built the RCA Mark I and Mark II synthesizers with Harry F. Olson.',
    story: 'Belar worked as a research engineer in acoustics at RCA’s laboratories in Princeton, New Jersey, for thirty-eight years. He worked on high-fidelity recording and a phonetic typewriter that turned speech into text. With Harry F. Olson he designed the RCA Mark I synthesizer in the 1950s and its successor, the Mark II, which was installed at the Columbia-Princeton Electronic Music Center in 1957. Composers such as Milton Babbitt used it through the 1960s.',
    innovations: ['Co-designed the RCA Mark II, which combined tone generators, filters and envelope shaping with a punched-paper sequencer.'] },
  { id: 'yevgeny-murzin', name: 'Yevgeny Murzin', born: '1914', died: '1970', country: 'RU', companies: [],
    summary: 'Russian engineer who built the ANS synthesizer, played by drawing on glass.',
    story: 'Murzin was born in Samara and trained as an engineer in Moscow. During the Second World War he developed an anti-aircraft detection device that the Soviet Army adopted. He worked on the ANS in his own time from 1937, basing it on the optical sound recording used in film, and completed it in 1957. He named it after the composer Alexander Nikolayevich Scriabin. In 1958 he set up a laboratory in Moscow round the instrument, and composers including Eduard Artemyev, Alfred Schnittke and Sofia Gubaidulina worked with it.',
    innovations: ['Built the ANS, in which the composer scratches marks on a coated glass plate and the instrument reads them with light as 720 pure tones across ten octaves.'] },
  { id: 'daphne-oram', name: 'Daphne Oram', born: '1925', died: '2003', country: 'GB', companies: ['BBC Radiophonic Workshop', 'Oramics Studios'],
    summary: 'British composer who co-founded the BBC Radiophonic Workshop and invented Oramics, a way of making sound from drawings.',
    story: 'Oram joined the BBC in 1942 as a studio engineer and experimented with tape recorders and oscillators in her own time, and in 1957 she made the first wholly electronic score broadcast by the BBC. In 1958 she set up the BBC Radiophonic Workshop with Desmond Briscoe, but she left within a year to work on her own. At Tower Folly, her studio in Kent, she developed Oramics, in which shapes drawn on strips of 35mm film control the pitch, loudness and tone of the music. Helped by grants from the Gulbenkian Foundation and the engineer Graham Wrench, she had a working machine by 1966. It is now in the Science Museum in London.',
    innovations: ['Invented Oramics, which turns shapes drawn on 35mm film into sound, with separate strips controlling pitch, volume and waveform.',
      'Co-founded the BBC Radiophonic Workshop in 1958 and was its first studio manager.'] },
  { id: 'serge-tcherepnin', name: 'Serge Tcherepnin', born: '1941', country: 'US', companies: ['Serge Modular Music Systems'],
    summary: 'French-born American composer who designed the Serge modular synthesizer.',
    story: 'Tcherepnin was born near Paris into a family of composers and studied at Harvard and in Europe with Nadia Boulanger, Karlheinz Stockhausen and others. He taught at the California Institute of the Arts, where he worked with Morton Subotnick and came across Buchla’s modular systems. He began designing modules there that students could build for themselves, and in 1974 he founded Serge Modular Music Systems to make them. The company worked from California until it closed in 1986, when he returned to France. He later advised Random*Source, a German company that makes Serge modules again.',
    innovations: ['Designed modules that each did more than one job depending on how they were patched, such as a slope generator that could be an envelope, an oscillator or a slew limiter.',
      'Sold the Serge system partly as kits at low cost so that students and musicians could build their own modular synthesizers.'] },
  { id: 'dave-rossum', name: 'Dave Rossum', born: '1948', country: 'US', companies: ['E-mu Systems', 'Creative Technology', 'Rossum Electro-Music'],
    summary: 'American engineer who co-founded E-mu Systems and designed its modular synthesizers, the Emulator samplers and the SP-1200.',
    story: 'Rossum studied biology at Caltech and was a student in Santa Cruz, California, when he began building synthesizers with friends in the early 1970s, which led to E-mu Systems, run with Scott Wedge. E-mu first sold modular synthesizers, and Rossum designed the SSM2040 filter chip used in the early Prophet-5. E-mu’s Emulator sampler of 1981 cost a fraction of the Fairlight CMI, and its SP-12 and SP-1200 drum samplers were taken up by hip-hop producers. After Creative Technology bought E-mu in 1993 he became its chief scientist, and in 2015 he founded Rossum Electro-Music to make Eurorack modules.',
    innovations: ['Patented a digitally scanned polyphonic keyboard in 1973, which E-mu licensed to Oberheim and Sequential Circuits for their polysynths.',
      'Designed the Emulator, a sampling keyboard sold in 1981 for $7,900, about a quarter of the price of a Fairlight CMI.',
      'Designed the SSM2040 filter chip used in early revisions of the Sequential Prophet-5.'] },
  { id: 'scott-wedge', name: 'Scott Wedge', country: 'US', companies: ['E-mu Systems'],
    summary: 'American engineer and businessman who co-founded E-mu Systems and was its president.',
    story: 'Wedge joined Dave Rossum and his friends in Santa Cruz in the early 1970s and became president of E-mu Systems. He ran the business side as the company sold modular synthesizers and licensed its keyboard-scanning patent to Oberheim and Sequential Circuits. With Rossum he saw that falling memory prices made sampling affordable, and E-mu released the Emulator in 1981, followed by the Emulator II and the SP-1200. E-mu was sold to Creative Technology in 1993.',
    innovations: ['Led E-mu as it moved from modular synthesizers to sampling, bringing out the Emulator in 1981 at a price studios and touring musicians could pay.'] },
  { id: 'john-simonton', name: 'John Simonton', born: '1943', died: '2005', country: 'US', companies: ['PAiA Electronics'],
    summary: 'American engineer who founded PAiA Electronics and designed low-cost synthesizer kits.',
    story: 'Simonton was born in Honolulu, studied electrical engineering in Louisiana and was working at Tinker Air Force Base in Oklahoma when he founded PAiA Electronics in Oklahoma City in 1967, selling electronics kits by mail order. He published designs in hobby magazines and turned to music, with the Gnome, a small synthesizer sold for under $50 in 1974, and the 2700 and 4700 modular systems, which cost a fraction of a Moog or ARP. PAiA also sold one of the earliest programmable drum machines. He ran the company until he died of cancer in 2005.',
    innovations: ['Sold modular synthesizers as kits for a few hundred dollars, when systems from Moog and ARP cost thousands.',
      'Sold the P4700J, a modular system controlled by a microcomputer, in the 1970s.'] },
  { id: 'bill-hemsath', name: 'Bill Hemsath', country: 'US', companies: ['R. A. Moog Co.', 'Musonics'],
    summary: 'American engineer at Moog who built the first Minimoog prototype.',
    story: 'Hemsath was an engineer at R. A. Moog in Trumansburg, New York. In late 1969, with Chad Hunt, he wired five discarded modular modules to a three-octave keyboard in a wooden case, the prototype later called the Model A. Robert Moog backed the idea, and Hemsath led the work through the Model B and C prototypes with Jim Scott and Chad Hunt, designing the pitch and modulation wheels of the Model D to Moog’s specification. The first production Minimoog shipped in November 1970. He later co-founded Musonics with Bill Waytena, where he worked on the Sonic Five and Sonic Six.',
    innovations: ['Built the first Minimoog prototype, hard-wiring modular modules together so the instrument needed no patch cords.',
      'Designed the Minimoog’s pitch and modulation wheels, which most later synthesizers copied.'] },
  { id: 'jim-scott', name: 'Jim Scott', country: 'US', companies: ['R. A. Moog Co.'],
    summary: 'American engineer at Moog who worked on the Minimoog prototypes.',
    story: 'Scott graduated in electrical engineering from Berkeley in 1969 and joined Moog that September after meeting Robert Moog at an Audio Engineering Society convention. Among his first jobs was the final checkout of the modular system sent to Keith Emerson. He worked with Bill Hemsath and Chad Hunt on the Model B prototype of the Minimoog in 1970 and on the filter, amplifier and envelope circuits of the Model C. He also designed special-order modules, including a vocoder for the State University of New York.',
    innovations: ['Designed the filter, amplifier and envelope circuits of the Minimoog Model C prototype, the stage before production.'] },
  { id: 'ken-freeman', name: 'Ken Freeman', born: '1946', country: 'GB', companies: [],
    summary: 'British keyboard player who invented the string synthesizer.',
    story: 'Freeman was playing keyboards in the band the Unsquare Men in 1966 when he ran a Selmer Clavioline through a tape echo and found that the delayed, slightly detuned copy sounded like a section of strings. He taught himself electronics and built a polyphonic version using the divide-down circuits of an electronic organ, making several prototypes from 1969. Lowrey, part of the Chicago Musical Instrument Company, made it as the Freeman String Symphonizer from 1974. He worked as a session player, playing synthesizers on Jeff Wayne’s “The War of the Worlds”, and wrote the themes for the BBC’s “Casualty” and “Holby City”.',
    innovations: ['Made strings from an electronic keyboard by mixing the tone with delayed, pitch-wavering copies of itself, the chorus effect used in string machines that followed.'] },
  { id: 'wolfgang-palm', name: 'Wolfgang Palm', born: '1950', country: 'DE', companies: ['PPG', 'Waldorf'],
    summary: 'German designer who founded PPG and invented wavetable synthesis in the PPG Wave.',
    story: 'Palm founded Palm Products GmbH (PPG) in Hamburg in 1975 and at first built modular synthesizers, among others for Tangerine Dream. He began using digital oscillators in place of voltage-controlled ones, which led to the Wavecomputer 360 and then the PPG Wave 2 of 1981, followed by the Wave 2.2 and 2.3. The Wave combined wavetables with analogue filters and was used by Thomas Dolby, Depeche Mode and David Bowie. PPG closed in 1987 as cheaper digital synthesizers arrived, and Waldorf, formed from its remains, carried the wavetable idea on in the Microwave of 1989. Palm has since designed software and hardware instruments under his own name.',
    innovations: ['Invented wavetable synthesis: a table of single-cycle waveforms that the oscillator steps or sweeps through, so the tone changes as it plays.',
      'Put digital wavetable oscillators in front of analogue filters in the PPG Wave, an early hybrid synthesizer.',
      'Linked PPG instruments with his own parallel bus before MIDI existed.'] },
  { id: 'tony-furse', name: 'Tony Furse', born: '1938', country: 'AU', companies: ['Creative Strategies'],
    summary: 'Australian engineer whose Qasar M8 digital synthesizer became the basis of the Fairlight CMI.',
    story: 'Furse was born in Sydney and was building electronic instruments by the late 1950s. In 1972 he set up Creative Strategies in Sydney and, with backing from the Canberra School of Music, built the Qasar I and II, digital and hybrid synthesizers that did not reach production. In 1975 he completed the Qasar M8, an eight-voice digital synthesizer run by two microprocessors, whose sounds were drawn and edited with a light pen on a screen. In 1976 Peter Vogel and Kim Ryrie licensed the design for Fairlight, and it became the base of the Fairlight CMI. He shared the CSIRO Medal with them in 1987.',
    innovations: ['Built the Qasar M8, an eight-voice digital synthesizer with sounds drawn and edited by light pen on a screen, completed in 1975.'] },
  { id: 'peter-vogel', name: 'Peter Vogel', born: '1954', country: 'AU', companies: ['Fairlight', 'Fairlight Instruments'],
    summary: 'Australian engineer who co-founded Fairlight and developed the sampling of the Fairlight CMI.',
    story: 'Vogel founded Fairlight in Sydney in 1975 with his school friend Kim Ryrie, naming it after a harbour ferry. They licensed Tony Furse’s Qasar M8 and developed it into the Fairlight CMI. In 1978, finding that synthesized sounds were hard to make realistic, Vogel recorded a short burst of piano from the radio into the computer and played it back at different pitches, and the CMI became a sampling instrument when it was released in 1979. Its owners included Peter Gabriel, Kate Bush, Stevie Wonder and Herbie Hancock. In 2009 he re-established Fairlight Instruments and released the CMI-30A.',
    innovations: ['Used recorded sounds, played back at different pitches from a keyboard, as the main sound source of the Fairlight CMI, the first sampling instrument on sale.',
      'Named the technique “sampling” with Kim Ryrie.'] },
  { id: 'kim-ryrie', name: 'Kim Ryrie', country: 'AU', companies: ['Electronics Today International', 'Fairlight', 'Fairlight ESP', 'DEQX'],
    summary: 'Australian designer and publisher who co-founded Fairlight and developed the Fairlight CMI with Peter Vogel.',
    story: 'Ryrie, son of the magazine publisher Colin Ryrie, launched Electronics Today International in 1970 and published the ETI 4600, an analogue synthesizer readers built from monthly instalments. In 1975, frustrated by the limits of analogue synthesizers, he founded Fairlight with Peter Vogel, and they licensed Tony Furse’s Qasar M8 and developed it into the Fairlight CMI, released in 1979. When cheaper samplers undercut the CMI, he kept the company’s technology and formed Fairlight ESP, which made digital audio workstations for film and television. In 1997 he founded DEQX, which makes loudspeaker correction equipment.',
    innovations: ['Published the ETI 4600, a full synthesizer for magazine readers to build themselves, in the early 1970s.'] },
  { id: 'sydney-alonso', name: 'Sydney Alonso', country: 'US', companies: ['New England Digital'],
    summary: 'American engineer who co-designed the Synclavier and co-founded New England Digital.',
    story: 'Alonso worked with the Dartmouth College composer Jon Appleton and the student programmer Cameron Jones on a digital synthesizer, starting in March 1976. To build it they designed their own computer and software tools, and Alonso and Jones founded New England Digital in Vermont to sell them. The first Synclavier followed in 1977 and the Synclavier II in 1980, adding FM and additive synthesis and later sampling and recording to hard disk. Alonso and Jones hold patents on its note oscillator and on its partial-timbre synthesis. The company closed in 1993.',
    innovations: ['Co-designed the Synclavier, with Cameron Jones, around a computer they built themselves, and patented its high-resolution note oscillator.',
      'Built, with New England Digital, one of the first systems to record digital audio straight to hard disk, the Sample-to-Disk option of 1981.'] },
  { id: 'cameron-jones', name: 'Cameron Jones', country: 'US', companies: ['New England Digital', 'Synclavier Digital'],
    summary: 'American programmer who wrote the Synclavier’s software, co-founded New England Digital and later revived the Synclavier name.',
    story: 'Jones was a student at Dartmouth College when he began work on a digital synthesizer with Sydney Alonso and Jon Appleton in 1976, writing its software. He and Alonso founded New England Digital to sell the computer and the instrument, and the Synclavier grew into a studio system with synthesis, sampling and recording to disk, costing over $200,000 by the late 1980s. After the company closed in 1993 he bought back its intellectual property and the Synclavier name. He worked with Arturia on the Synclavier V software, released an iOS version, and in 2022 the Regen desktop synthesizer.',
    innovations: ['Wrote the Synclavier’s software, including its partial-timbre synthesis, which he patented with Sydney Alonso.'] },
  { id: 'ray-kurzweil', name: 'Ray Kurzweil', born: '1948', country: 'US', companies: ['Kurzweil Computer Products', 'Kurzweil Music Systems'],
    summary: 'American inventor who founded Kurzweil Music Systems and made the K250 sampling keyboard.',
    story: 'Kurzweil was born in New York and in 1976 introduced a reading machine for blind people that turned printed text into speech. Stevie Wonder became one of its first users and, in 1982, asked whether the same computer methods could reproduce acoustic instruments. Kurzweil founded Kurzweil Music Systems that year, with Wonder as adviser and Robert Moog as a consultant, and showed the K250 at the NAMM show in 1984. It played sampled instruments stored in ROM, compressed with a method the company called contoured sound modelling. The company was sold to Young Chang in 1990.',
    innovations: ['Made the K250, a keyboard with sampled acoustic instruments stored in ROM, so realistic piano, strings and brass were ready at switch-on with no disks to load.'] },
  { id: 'dieter-doepfer', name: 'Dieter Doepfer', country: 'DE', companies: ['Doepfer Musikelektronik'],
    summary: 'German engineer who founded Doepfer Musikelektronik and created the Eurorack format with the A-100.',
    story: 'Doepfer studied physics in Munich while playing in a band, repairing its equipment and building effects. From 1977 he made modules for the Formant, a synthesizer built from kits published in Elektor magazine, and later restored a Moog modular system. His company, based in Gräfelfing near Munich, made MIDI equipment and in 1992 released the MAQ16/3 sequencer, developed with Kraftwerk. In 1995 he introduced the A-100 modular system, using 3U rack-mount panels and 3.5 mm patch cables.',
    innovations: ['Set the Eurorack format with the A-100 in 1995: modules of a fixed height and power supply that other makers adopted, so modules from many companies fit one case.',
      'Developed the MAQ16/3 analogue sequencer with Kraftwerk in 1992.'] },
];
